/*
 * Live Sync product repair page (generated by deploy_livesync.py, served by CloudFront).
 *
 * The customer is on a PHONE CALL.  The Connect flow emailed them https://<page>/#t=<token>.
 * This page:
 *   1. reads the token from the URL fragment (never sent to a server by the browser) and removes it
 *      from the address bar (kept in sessionStorage for reloads);
 *   2. POSTs it to /api/session, which returns the call's contact id and the Live Sync keys while the
 *      link is valid and the call is active;
 *   3. starts Touchpoint with input "external": no UI and no contact of its own, only the Live Sync
 *      channel of the phone call (liveSync.contactId);
 *   4. advertises the actions of the current step with one sendContext() call (scopes + actions):
 *        product - select_product          (3 dummy products)
 *        model   - select_model, change_product   (4 dummy models)
 *        fault   - change_product, change_model   (described by voice only, no page field)
 * Automatic page context is off, so only these declarations reach the assistant.  All dynamic text
 * is set with textContent, never innerHTML.
 */
(function () {
  "use strict";

  var BASE = window.LIVESYNC_CONFIG || {};
  var T = BASE.text || {};
  var CATALOG = BASE.catalog || { products: [], models: [] };
  var TOKEN_KEY = "livesync-demo-token";
  var SCOPES = {
    product: ["repair", "product_selection"],
    model: ["repair", "model_selection"],
    fault: ["repair", "fault_description"]
  };
  var STEPS = ["product", "model", "fault"];

  var state = { step: "product", productId: null, modelId: null, pickedBy: { product: null, model: null } };
  var touchpoint = null;
  var status = { kind: "loading", text: "" };

  // ------------------------------------------------------------------ helpers

  function t(key) {
    return Object.prototype.hasOwnProperty.call(T, key) ? T[key] : key;
  }

  function el(tag, attrs) {
    var node = document.createElement(tag);
    var a = attrs || {};
    Object.keys(a).forEach(function (k) {
      var v = a[k];
      if (v === null || v === undefined || v === false) return;
      if (k === "text") node.textContent = v;
      else if (k === "className") node.className = v;
      else if (k === "onClick") node.addEventListener("click", v);
      else node.setAttribute(k, v === true ? "" : String(v));
    });
    for (var i = 2; i < arguments.length; i++) {
      var child = arguments[i];
      if (child === null || child === undefined || child === false) continue;
      if (Array.isArray(child)) child.forEach(function (c) { if (c) node.appendChild(c); });
      else node.appendChild(typeof child === "string" ? document.createTextNode(child) : child);
    }
    return node;
  }

  function findProduct(id) {
    return CATALOG.products.filter(function (p) { return p.id === id; })[0] || null;
  }

  function findModel(id) {
    return CATALOG.models.filter(function (m) { return m.id === id; })[0] || null;
  }

  /** The agent sends the object described by the schema; accept a bare string too. */
  function payloadValue(payload, key) {
    if (typeof payload === "string") return payload;
    if (payload && typeof payload === "object" && typeof payload[key] === "string") return payload[key];
    return null;
  }

  // ------------------------------------------------------------------ token

  function readToken() {
    var match = /(?:^|[#&])t=([A-Za-z0-9_\-]+\.[A-Za-z0-9_\-]+)/.exec(window.location.hash || "");
    var token = match ? match[1] : null;
    try {
      if (token) {
        window.sessionStorage.setItem(TOKEN_KEY, token);
        // Keep the token out of the address bar (copy / share / screenshots).
        window.history.replaceState(null, "", window.location.pathname + window.location.search);
      } else {
        token = window.sessionStorage.getItem(TOKEN_KEY);
      }
    } catch (e) {
      // sessionStorage may be disabled; the token from the fragment still works for this load.
    }
    return token;
  }

  // ------------------------------------------------------------------ Live Sync contract

  function selectionSummary() {
    var p = findProduct(state.productId);
    var m = findModel(state.modelId);
    return t("current_selection") + ": " + (p ? p.name : t("nothing_selected")) + " / " +
      (m ? m.name : t("nothing_selected"));
  }

  function selectProductAction() {
    var listing = CATALOG.products.map(function (p) {
      return p.id + " = " + p.name + " (" + p.description + ")";
    }).join("; ");
    return {
      action: "select_product",
      description: t("action_select_product") + " " + t("available") + ": " + listing + ". " + selectionSummary(),
      schema: {
        type: "object",
        properties: {
          productId: {
            type: "string",
            description: t("param_product_id") + " " + t("available") + ": " + listing,
            enum: CATALOG.products.map(function (p) { return p.id; })
          }
        },
        required: ["productId"]
      },
      handler: function (payload) {
        selectProduct(payloadValue(payload, "productId"), "assistant");
      }
    };
  }

  function selectModelAction() {
    var listing = CATALOG.models.map(function (m) {
      return m.id + " = " + m.name + " (" + m.description + ")";
    }).join("; ");
    return {
      action: "select_model",
      description: t("action_select_model") + " " + t("available") + ": " + listing + ". " + selectionSummary(),
      schema: {
        type: "object",
        properties: {
          modelId: {
            type: "string",
            description: t("param_model_id") + " " + t("available") + ": " + listing,
            enum: CATALOG.models.map(function (m) { return m.id; })
          }
        },
        required: ["modelId"]
      },
      handler: function (payload) {
        selectModel(payloadValue(payload, "modelId"), "assistant");
      }
    };
  }

  function changeAction(name, descriptionKey, step) {
    return {
      action: name,
      description: t(descriptionKey) + " " + selectionSummary(),
      handler: function () { goTo(step); }
    };
  }

  /** Scopes and actions of the current step, always sent together in one sendContext call. */
  function declaration() {
    var actions;
    if (state.step === "product") {
      actions = [selectProductAction()];
    } else if (state.step === "model") {
      actions = [selectModelAction(), changeAction("change_product", "action_change_product", "product")];
    } else {
      actions = [
        changeAction("change_product", "action_change_product", "product"),
        changeAction("change_model", "action_change_model", "model")
      ];
    }
    return { scopes: SCOPES[state.step], actions: actions };
  }

  function advertise() {
    if (!touchpoint) return;
    Promise.resolve(touchpoint.sendContext(declaration())).catch(function (err) {
      console.error("[livesync-demo] sendContext failed", err);
    });
  }

  // ------------------------------------------------------------------ state changes

  function selectProduct(id, by) {
    if (!findProduct(id)) {
      console.warn("[livesync-demo] unknown product", id);
      return;
    }
    if (state.productId !== id) state.modelId = null;
    state.productId = id;
    state.pickedBy.product = by;
    state.step = "model";
    update();
  }

  function selectModel(id, by) {
    if (!findModel(id)) {
      console.warn("[livesync-demo] unknown model", id);
      return;
    }
    if (!state.productId) {
      state.step = "product";
      update();
      return;
    }
    state.modelId = id;
    state.pickedBy.model = by;
    state.step = "fault";
    update();
  }

  function goTo(step) {
    if (STEPS.indexOf(step) < 0) return;
    if (step === "model" && !state.productId) step = "product";
    state.step = step;
    update();
  }

  function update() {
    render();
    advertise();
  }

  // ------------------------------------------------------------------ rendering

  function renderStepper() {
    var labels = { product: t("step_product"), model: t("step_model"), fault: t("step_fault") };
    var current = STEPS.indexOf(state.step);
    return el("ol", { className: "stepper" }, STEPS.map(function (step, i) {
      var cls = i < current ? "done" : i === current ? "current" : "todo";
      return el("li", { className: "step " + cls, "aria-current": i === current ? "step" : null },
        el("span", { className: "step-index", "aria-hidden": "true", text: String(i + 1) }),
        el("span", { className: "step-label", text: labels[step] }));
    }));
  }

  function card(item, selected, pickedByAssistant, onPick, enabled) {
    return el("li", null,
      el("button", {
        type: "button",
        className: "card" + (selected ? " selected" : "") + (selected && pickedByAssistant ? " by-assistant" : ""),
        "aria-pressed": selected ? "true" : "false",
        disabled: !enabled,
        onClick: onPick
      },
        item.icon ? el("span", { className: "card-icon", "aria-hidden": "true", text: item.icon }) : null,
        el("span", { className: "card-title", text: item.name }),
        el("span", { className: "card-desc", text: item.description }),
        selected && pickedByAssistant ? el("span", { className: "badge", text: t("picked_by_assistant") }) : null));
  }

  function renderPanel() {
    var live = status.kind === "connected";
    if (state.step === "product") {
      return el("section", { className: "panel", "aria-labelledby": "panel-heading" },
        el("h2", { id: "panel-heading", text: t("product_heading") }),
        el("ul", { className: "cards cards-3" }, CATALOG.products.map(function (p) {
          return card(p, state.productId === p.id, state.pickedBy.product === "assistant",
            function () { selectProduct(p.id, "caller"); }, live);
        })));
    }
    if (state.step === "model") {
      var product = findProduct(state.productId);
      return el("section", { className: "panel", "aria-labelledby": "panel-heading" },
        el("h2", { id: "panel-heading", text: t("model_heading") }),
        product ? el("p", { className: "panel-sub", text: product.name }) : null,
        el("ul", { className: "cards cards-4" }, CATALOG.models.map(function (m) {
          return card(m, state.modelId === m.id, state.pickedBy.model === "assistant",
            function () { selectModel(m.id, "caller"); }, live);
        })));
    }
    return el("section", { className: "panel", "aria-labelledby": "panel-heading" },
      el("h2", { id: "panel-heading", text: t("fault_heading") }),
      el("div", { className: "fault-hint" },
        el("span", { className: "mic", "aria-hidden": "true", text: "📞" }),
        el("p", { text: t("fault_hint") })));
  }

  function renderSummary() {
    var p = findProduct(state.productId);
    var m = findModel(state.modelId);
    var live = status.kind === "connected";
    function row(label, value, step) {
      return el("div", { className: "summary-row" },
        el("dt", { text: label }),
        el("dd", null,
          el("span", { className: value ? "" : "muted", text: value || t("summary_empty") }),
          step && value && live ? el("button", {
            type: "button", className: "link", onClick: function () { goTo(step); },
            "aria-label": t("change") + " " + label, text: t("change")
          }) : null));
    }
    return el("aside", { className: "summary", "aria-labelledby": "summary-heading" },
      el("h2", { id: "summary-heading", text: t("summary_heading") }),
      el("dl", null,
        row(t("summary_product"), p && p.name, "product"),
        row(t("summary_model"), m && m.name, "model"),
        row(t("summary_fault"), state.step === "fault" ? t("summary_fault_value") : "", null)));
  }

  function render() {
    var app = document.getElementById("app");
    app.textContent = "";
    app.appendChild(el("header", { className: "header" },
      el("h1", { text: t("title") }),
      el("p", { className: "subtitle", text: t("subtitle") })));
    var alert = status.kind !== "loading" && status.kind !== "connected";
    app.appendChild(el("p", {
      className: "status status-" + status.kind, role: alert ? "alert" : "status", text: status.text
    }));
    app.appendChild(renderStepper());
    app.appendChild(el("main", { className: "layout", id: "main" }, renderPanel(), renderSummary()));
    app.setAttribute("aria-busy", status.kind === "loading" ? "true" : "false");
  }

  function setStatus(kind, key) {
    status = { kind: kind, text: t(key) };
    render();
  }

  // ------------------------------------------------------------------ start

  var ERROR_STATUS = {
    LINK_EXPIRED: "status_expired",
    CALL_ENDED: "status_call_ended",
    LIVE_SYNC_KEYS_NOT_CONFIGURED: "status_not_ready",
    INVALID_TOKEN: "status_no_token"
  };

  function fetchSession(token) {
    return window.fetch(BASE.sessionPath || "/api/session", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ token: token }),
      cache: "no-store",
      credentials: "omit"
    }).then(function (resp) {
      return resp.json().catch(function () { return {}; }).then(function (body) {
        if (!resp.ok) {
          var err = new Error(body.error || ("HTTP " + resp.status));
          err.code = body.error;
          throw err;
        }
        return body;
      });
    });
  }

  function start() {
    var token = readToken();
    if (!token) {
      setStatus("error", "status_no_token");
      return;
    }
    if (!window.amazonConnectTouchpoint || typeof window.amazonConnectTouchpoint.create !== "function") {
      setStatus("error", "status_error");
      return;
    }
    setStatus("loading", "status_loading");
    fetchSession(token).then(function (session) {
      return window.amazonConnectTouchpoint.create({
        config: { region: session.region },
        // Must match the published ACXD application (Live Sync channel connect-<languageCode>).
        languageCode: session.languageCode || BASE.languageCode,
        input: "external",
        liveSync: {
          apiKey: session.liveSync.apiKey,
          deploymentKey: session.liveSync.deploymentKey,
          contactId: session.contactId,
          automaticContext: false
        }
      });
    }).then(function (instance) {
      touchpoint = instance;
      setStatus("connected", "status_connected");
      advertise();
    }).catch(function (err) {
      console.error("[livesync-demo] start failed", err && (err.code || err.message));
      var key = (err && ERROR_STATUS[err.code]) || "status_error";
      if (err && (err.code === "LINK_EXPIRED" || err.code === "CALL_ENDED" || err.code === "INVALID_TOKEN")) {
        try { window.sessionStorage.removeItem(TOKEN_KEY); } catch (e) { /* ignore */ }
      }
      setStatus("error", key);
    });
  }

  render();
  start();
})();
